fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> Vec<char> {
    let min_len = std::cmp::min(str1.len(), str2.len());
    let mut prefix_len = 0;

    while prefix_len < min_len {
        if str1[prefix_len] != str2[prefix_len] {
            break;
        }
        prefix_len += 1;
    }

    // prefix_len is the length of longest common prefix satisfying:
    // - prefix characters equal in both strings
    // - either prefix_len == str1.len() or prefix_len == str2.len() (one input is prefix of other)
    //   OR the next character after prefix_len differs in the two inputs

    str1[0..prefix_len].to_vec()
}